const app=document.querySelector('#app'),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=v=>v==null?'—':Number(v).toFixed(1),fmtConsensus=o=>o&&o.consensusNote==='single_respondent'?L('Non calculable','Not calculable'):fmt(o?.consensus); function notice(message){let n=document.querySelector('#notice');if(!n){n=document.createElement('div');n.id='notice';document.body.appendChild(n)}n.className='notice';n.innerHTML=`<div><b>${L('Information','Information')}</b><p>${esc(message)}</p><button onclick="this.closest('.notice').remove()">${L('Fermer','Close')}</button></div>`} const api=(p,o={})=>fetch(p,{headers:{'Content-Type':'application/json'},...o}).then(async r=>{let x=await r.json();if(!r.ok)throw Error(x.error||L('Action impossible.','Action failed.'));return x}); window.addEventListener('unhandledrejection',e=>{e.preventDefault();notice(e.reason?.message||L('Action impossible. Veuillez réessayer.','Action failed. Please try again.'));}); window.addEventListener('error',e=>{if(e.message)notice(L('Une action ne peut pas être réalisée : ','An action could not be completed: ')+e.message)});let T=[],S=[];
// Mode sombre : préférence par navigateur (pas de compte requis pour l'appliquer), appliquée tôt par
// index.html pour éviter un flash clair→sombre, ré-affirmée ici pour les navigateurs sans script
// bloquant. N'affecte jamais le rapport imprimé ni les exports (voir style.css).
function getTheme(){try{return localStorage.getItem('epc-theme')==='dark'?'dark':'light'}catch(e){return 'light'}}
function toggleTheme(btn){let next=getTheme()==='dark'?'light':'dark';try{localStorage.setItem('epc-theme',next)}catch(e){}document.documentElement.dataset.theme=next;if(btn){btn.textContent=next==='dark'?'☾':'☀';btn.setAttribute('aria-pressed',String(next==='dark'));btn.title=next==='dark'?'Passer en mode clair':'Passer en mode sombre'}}
// Langue de l'interface : français par défaut, mémorisée par navigateur (comme le thème). L(fr,en)
// traduit uniquement les libellés fixes de l'interface — jamais les données saisies par les
// utilisateurs (noms de mission, domaines/indicateurs personnalisés, réponses des participants),
// qui ne passent jamais par L() et restent donc toujours affichées telles qu'elles ont été saisies.
function getLang(){try{return localStorage.getItem('epc-lang')==='en'?'en':'fr'}catch(e){return 'fr'}}
function L(fr,en){return getLang()==='en'?en:fr}
// Rejoue la navigation qui a produit l'écran actuel (même logique que le clic correspondant dans la
// barre latérale) pour redessiner l'écran dans la nouvelle langue, sans perdre la mission ouverte.
// Un formulaire de sous-écran non enregistré (ex. édition d'un domaine) revient à son écran parent :
// compromis assumé, aucune saisie n'est perdue silencieusement côté serveur (rien n'était encore
// enregistré), seul l'écran affiché change.
function rerenderCurrent(){let item=SIDEBAR_ITEMS().find(it=>it.key===window.currentHelpKey);if(item&&(!item.need||window.currentSessionId))item.go();else load()}
function toggleLang(btn){let next=getLang()==='en'?'fr':'en';try{localStorage.setItem('epc-lang',next)}catch(e){}document.documentElement.lang=next;rerenderCurrent()}
async function load(){[T,S]=await Promise.all([api('/api/templates'),api('/api/sessions')]);shell('home','',L('Diagnostic EPC / SENEVAL','EPC / SENEVAL diagnostic'),L('Préparation, collecte et restitution d’ateliers','Preparation, collection and reporting of workshops'),null);home()};
// Fonction (pas une const figée) : même raison que HELP_SCREENS()/SIDEBAR_ITEMS() — L() doit être
// réévalué à chaque appel, pas figé au premier chargement du script.
function back(){return `<button class="ghost" onclick="load()">← ${L('Retour à l’accueil','Back to home')}</button>`}
window.currentSessionId=null;
const DOMAIN_COLORS=['var(--domain-1)','var(--domain-2)','var(--domain-3)','var(--domain-4)','var(--domain-5)','var(--domain-6)','var(--domain-7)'];
// Fonction (pas une const figée) : les libellés traduits par L() doivent être réévalués à chaque
// appel pour refléter un changement de langue survenu après le premier chargement du script.
function SIDEBAR_ITEMS(){return [
  {key:'home',label:L('Accueil','Home'),ic:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 11l8-7 8 7"/><path d="M6 10v9a1 1 0 0 0 1 1h10a1 1 0 0 0 1-1v-9"/></svg>',need:false,go:()=>load()},
  {key:'config',label:L('Configuration','Configuration'),ic:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 13a7.7 7.7 0 0 0 0-2l2-1.5-2-3.4-2.3.9a7.6 7.6 0 0 0-1.7-1L15 3h-4l-.4 2.5a7.6 7.6 0 0 0-1.7 1l-2.3-.9-2 3.4L6.6 11a7.7 7.7 0 0 0 0 2l-2 1.5 2 3.4 2.3-.9c.5.4 1.1.8 1.7 1L10 21h4l.4-2.5c.6-.2 1.2-.6 1.7-1l2.3.9 2-3.4-2-1.5z"/></svg>',need:false,go:()=>window.currentSessionId?configuration(window.currentSessionId):notice(L('Créez ou ouvrez un atelier pour accéder à sa configuration.','Create or open a workshop to access its configuration.'))},
  {key:'questionnaire',label:L('Questionnaire','Questionnaire'),ic:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M6 3.5h8l4 4V20a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V4.5a1 1 0 0 1 1-1z"/><path d="M14 3.5V8h4"/><path d="M8.5 12.5h7M8.5 15.5h7"/></svg>',need:true,go:()=>preview(window.currentSessionId)},
  {key:'participants',label:L('Participants','Participants'),ic:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="8" r="3.2"/><path d="M2.8 19c.6-3 3-5 6.2-5s5.6 2 6.2 5"/><circle cx="17.5" cy="8.5" r="2.6"/><path d="M15.5 13.6c2.6.4 4.4 2.2 4.9 4.9"/></svg>',need:true,go:()=>moderator(window.currentSessionId)},
  {key:'collecte',label:L('Collecte','Collection'),ic:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="4" width="7" height="7" rx="1"/><rect x="13" y="4" width="7" height="7" rx="1"/><rect x="4" y="13" width="7" height="7" rx="1"/><path d="M15 15h5M17.5 13v5"/></svg>',need:true,go:()=>moderator(window.currentSessionId)},
  {key:'resultats',label:L('Résultats','Results'),ic:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 20V10M11 20V4M18 20v-7"/></svg>',need:true,go:()=>diagnostic(window.currentSessionId)},
  {key:'recommandations',label:L('Recommandations','Recommendations'),ic:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3a6 6 0 0 0-3.5 10.9c.5.4.8 1 .8 1.6v.5h5.4v-.5c0-.6.3-1.2.8-1.6A6 6 0 0 0 12 3z"/><path d="M9.5 19h5M10.5 21.5h3"/></svg>',need:true,go:()=>recommendationsView(window.currentSessionId)},
  {key:'rapport',label:L('Rapport','Report'),ic:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M6 3.5h8l4 4V20a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V4.5a1 1 0 0 1 1-1z"/><path d="M8.5 11h7M8.5 14h7M8.5 17h4"/></svg>',need:true,go:()=>finalReport(window.currentSessionId)},
]}
function renderSidebar(active){
  let cur=window.currentSessionSummary;
  return `<div class="sidebar-brand"><div class="logo"></div><div><b>EPC / SENEVAL</b><span>Diagnostic</span></div></div>
  <nav class="sidebar-nav">${SIDEBAR_ITEMS().map(it=>`<button class="${it.key===active?'active':''}" ${it.need&&!window.currentSessionId?'disabled':''} onclick="(${it.go.toString()})()"><span class="nav-ic">${it.ic}</span>${it.label}</button>`).join('')}</nav>
  ${cur?`<div class="sidebar-current"><div class="dot-row"><span class="dot"></span>${L('Atelier actuel','Current workshop')}</div><div class="name">${esc(cur.name)}</div><div class="meta">${esc(cur.location||'—')}${cur.date?' · '+esc(cur.date):''}</div><div class="status-row"><span>${L('Statut','Status')}</span><span class="badge-mini">${esc(cur.statusLabel||L('Préparation','Preparation'))}</span></div><div class="progress"><span style="width:${cur.pct??0}%"></span></div><button onclick="moderator('${cur.id}')">${L('Voir le tableau de bord','View dashboard')} →</button></div>`:''}
  ${window.currentUser?`<div class="sidebar-user"><div class="name">${esc(window.currentUser.displayName||window.currentUser.email)}</div><button class="ghost" onclick="doLogout()">${L('Se déconnecter','Log out')}</button></div>`:''}`;
}
function renderTopbar(title,subtitle,cycleStage){
  let stages=[['config',L('CONFIGURER','SET UP')],['collecte',L('COLLECTER','COLLECT')],['traiter',L('TRAITER','PROCESS')],['analyse',L('ANALYSER','ANALYSE')],['restitution',L('RESTITUER','REPORT')]];
  let dark=getTheme()==='dark',lang=getLang();
  return `<div><h1>${esc(title||'')}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><div class="cycle-nav">${stages.map(([k,l])=>`<div class="cycle-step ${k===cycleStage?'active':''}"><span class="cycle-ic">${k===cycleStage?'●':'○'}</span>${l}</div>`).join('')}</div><button class="topbar-lang" title="${L('Switch to English','Passer en français')}" onclick="toggleLang(this)">${lang==='en'?'EN':'FR'}</button><button class="topbar-theme" title="${dark?L('Passer en mode clair','Switch to light mode'):L('Passer en mode sombre','Switch to dark mode')}" aria-pressed="${dark}" onclick="toggleTheme(this)">${dark?'☾':'☀'}</button><button class="topbar-help" title="${L('Aide','Help')}" onclick="helpPanel()">?</button>`;
}
function HELP_SCREENS(){return{
  home:{title:L('Accueil','Home'),body:L(`
    <p>C’est le point de départ : la liste de tous vos ateliers de diagnostic.</p>
    <p class="help-callout"><b>Le parcours général :</b> CONFIGURER → COLLECTER → TRAITER → ANALYSER → RESTITUER.</p>
    <h3>Que faire ici ?</h3>
    <ol>
      <li><b>Nouveau diagnostic</b> pour créer une mission.</li>
      <li><b>Reprendre</b> pour continuer votre atelier le plus récent.</li>
      <li><b>Missions récentes</b> pour rouvrir n’importe quel atelier déjà créé.</li>
      <li><b>Modèles &amp; questionnaires</b> pour consulter ou dupliquer un questionnaire.</li>
    </ol>
    <p class="help-callout"><b>À retenir :</b> reprendre un atelier existant ne fait perdre aucune information déjà enregistrée.</p>
    <p><b>Étape suivante :</b> Configuration.</p>
    <h3>Espace utilisateur</h3>
    <p>Chaque compte dispose de son propre espace : vous ne voyez que vos propres ateliers et questionnaires personnels.</p>`,`
    <p>This is the starting point: the list of all your diagnostic workshops.</p>
    <p class="help-callout"><b>The overall journey:</b> SET UP → COLLECT → PROCESS → ANALYSE → REPORT.</p>
    <h3>What to do here?</h3>
    <ol>
      <li><b>New diagnostic</b> to create a mission.</li>
      <li><b>Resume</b> to continue your most recent workshop.</li>
      <li><b>Recent missions</b> to reopen any workshop already created.</li>
      <li><b>Models &amp; questionnaires</b> to view or duplicate a questionnaire.</li>
    </ol>
    <p class="help-callout"><b>Remember:</b> resuming an existing workshop never loses any information already saved.</p>
    <p><b>Next step:</b> Configuration.</p>
    <h3>User space</h3>
    <p>Each account has its own space: you only see your own workshops and personal questionnaires.</p>`)},
  config:{title:L('Configuration de la mission','Mission setup'),body:L(`
    <p>Cet écran sert à préparer la mission avant d’ouvrir la collecte auprès des participants.</p>
    <h3>Que faire, dans quel ordre ?</h3>
    <ol>
      <li><b>Informations de la mission</b> : nom, lieu, date, description.</li>
      <li><b>Participants prévus</b> : nombre indicatif, utilisé comme référence — différent du nombre réel de répondants, recalculé après la collecte.</li>
      <li><b>Questionnaire</b> : le modèle EPC / SENEVAL est utilisé par défaut. Vous pouvez le garder, en changer, ou modifier ses domaines/références/indicateurs.</li>
      <li><b>Échelle de notation</b> : renommez les niveaux ou ajustez leur nombre (2 à 9).</li>
    </ol>
    <p class="help-callout"><b>À retenir :</b> une fois que l’atelier a des réponses, le questionnaire et l’échelle sont verrouillés pour ne pas invalider les données déjà collectées — modifiez-les avant d’ouvrir la collecte.</p>
    <p><b>Étape suivante :</b> ouvrir la collecte.</p>
    <h3>Assistant IA — facultatif</h3>
    <p>L’assistant IA peut vous aider à interpréter les résultats, préparer l’analyse, explorer des hypothèses, formuler des recommandations et rédiger la synthèse du rapport. <b>Il ne modifie jamais les calculs EPC et ne décide pas à la place du groupe.</b></p>
    <ol>
      <li>Activer l’assistant IA.</li>
      <li>Choisir un fournisseur.</li>
      <li>Obtenir une clé API <span class="text-meta">(le « ? » à côté du champ Clé API explique comment, selon le fournisseur choisi)</span>.</li>
      <li>Coller la clé.</li>
      <li>Choisir le modèle recommandé.</li>
      <li>Tester l’assistant IA.</li>
    </ol>
    <p><b>Badges</b> <span class="badge ai-badge" data-pricing="GRATUIT">GRATUIT</span> <span class="badge ai-badge" data-pricing="ESSAI">ESSAI</span> <span class="badge ai-badge" data-pricing="PAYANT">PAYANT</span> : ces indications concernent l’accès à l’API du fournisseur (pas son usage grand public) et peuvent évoluer.</p>
    <p class="help-callout"><b>À retenir :</b> la clé API est personnelle. Ne la partagez pas avec les participants. Une suggestion de l’assistant IA n’est jamais enregistrée automatiquement : c’est toujours vous, le pilote, qui décidez explicitement de retenir (ou non) ce qu’il propose.</p>
    <p>Lorsque vous utilisez une fonction IA, les données nécessaires à cette analyse sont transmises au fournisseur sélectionné. Les réponses individuelles nominatives et les informations techniques inutiles ne sont pas transmises. EPC / SENEVAL fonctionne normalement si l’IA est désactivée.</p>
    <p class="help-callout"><b>En cas de problème :</b> clé API refusée → vérifiez la clé, le fournisseur, le quota ou le modèle. Assistant IA indisponible → vous pouvez poursuivre l’atelier normalement, sans IA.</p>`,`
    <p>This screen is used to prepare the mission before opening collection to participants.</p>
    <h3>What to do, in which order?</h3>
    <ol>
      <li><b>Mission information</b>: name, location, date, description.</li>
      <li><b>Expected participants</b>: an indicative number used as a reference — different from the actual number of respondents, recalculated after collection.</li>
      <li><b>Questionnaire</b>: the EPC / SENEVAL model is used by default. You can keep it, change it, or edit its domains/references/indicators.</li>
      <li><b>Rating scale</b>: rename the levels or adjust their number (2 to 9).</li>
    </ol>
    <p class="help-callout"><b>Remember:</b> once the workshop has responses, the questionnaire and the scale are locked to avoid invalidating already-collected data — edit them before opening collection.</p>
    <p><b>Next step:</b> open collection.</p>
    <h3>AI assistant — optional</h3>
    <p>The AI assistant can help you interpret results, prepare the analysis, explore hypotheses, formulate recommendations and draft the report's synthesis. <b>It never changes the EPC calculations and never decides in the group's place.</b></p>
    <ol>
      <li>Enable the AI assistant.</li>
      <li>Choose a provider.</li>
      <li>Get an API key <span class="text-meta">(the "?" next to the API Key field explains how, depending on the chosen provider)</span>.</li>
      <li>Paste the key.</li>
      <li>Choose the recommended model.</li>
      <li>Test the AI assistant.</li>
    </ol>
    <p><b>Badges</b> <span class="badge ai-badge" data-pricing="GRATUIT">FREE</span> <span class="badge ai-badge" data-pricing="ESSAI">TRIAL</span> <span class="badge ai-badge" data-pricing="PAYANT">PAID</span>: these indications concern access to the provider's API (not its consumer product) and may change.</p>
    <p class="help-callout"><b>Remember:</b> the API key is personal. Do not share it with participants. An AI assistant suggestion is never saved automatically: it is always you, the facilitator, who explicitly decides whether to keep what it proposes.</p>
    <p>When you use an AI feature, the data needed for that analysis is sent to the selected provider. Named individual responses and unnecessary technical information are never sent. EPC / SENEVAL works normally if AI is disabled.</p>
    <p class="help-callout"><b>If something goes wrong:</b> API key rejected → check the key, provider, quota or model. AI assistant unavailable → you can continue the workshop normally, without AI.</p>`)},
  questionnaire:{title:L('Questionnaire','Questionnaire'),body:L(`
    <p>Cet écran présente la structure du questionnaire utilisé pour l’atelier.</p>
    <h3>Vocabulaire</h3>
    <p><b>Domaine</b> : grande thématique (ex. Gestion des ressources humaines). <b>Référence</b> : identifiant court d’une question. <b>Indicateur qualitatif / capacité</b> : la question elle-même, notée par les participants selon l’échelle définie en Configuration.</p>
    <h3>Que faire ?</h3>
    <ul>
      <li>Modifier, ajouter ou supprimer un domaine ou un indicateur.</li>
      <li>Importer une matrice Excel déjà préparée.</li>
      <li>Télécharger la matrice pour la modifier hors ligne puis la réimporter.</li>
    </ul>
    <p class="help-callout"><b>À retenir :</b> la numérotation et l’ordre d’affichage sont gérés automatiquement.</p>
    <p class="help-callout"><b>En cas de problème :</b> questionnaire vide → revenez ici pour ajouter au moins un domaine avec une question.</p>`,`
    <p>This screen shows the structure of the questionnaire used for the workshop.</p>
    <h3>Vocabulary</h3>
    <p><b>Domain</b>: broad theme (e.g. Human resources management). <b>Reference</b>: short identifier for a question. <b>Qualitative indicator / capacity</b>: the question itself, rated by participants using the scale defined in Configuration.</p>
    <h3>What to do?</h3>
    <ul>
      <li>Edit, add or remove a domain or an indicator.</li>
      <li>Import an already-prepared Excel matrix.</li>
      <li>Download the matrix to edit it offline, then re-import it.</li>
    </ul>
    <p class="help-callout"><b>Remember:</b> numbering and display order are managed automatically.</p>
    <p class="help-callout"><b>If something goes wrong:</b> empty questionnaire → come back here to add at least one domain with a question.</p>`)},
  collecte:{title:L('Collecte','Collection'),body:L(`
    <p>Cet écran sert à ouvrir la collecte des réponses et à en suivre l’avancement.</p>
    <h3>Que faire, dans quel ordre ?</h3>
    <ol>
      <li>Ouvrir la collecte.</li>
      <li>Afficher ou partager le QR code / le lien participant. Le bouton « Ouvrir participant » ouvre cette vue dans un nouvel onglet, sans fermer votre tableau de bord.</li>
      <li>Les participants répondent depuis leur téléphone.</li>
      <li>Suivre le nombre de participants et de questionnaires validés.</li>
      <li>Passer aux résultats lorsque la collecte est suffisante ou terminée.</li>
    </ol>
    <p class="help-callout"><b>À retenir :</b> les participants n’ont accès qu’au questionnaire — jamais à la configuration, ni à l’assistant IA.</p>
    <p class="help-callout"><b>En cas de problème :</b> QR inaccessible → vérifiez que l’adresse de l’application est bien accessible depuis le téléphone des participants.</p>`,`
    <p>This screen is used to open response collection and track its progress.</p>
    <h3>What to do, in which order?</h3>
    <ol>
      <li>Open collection.</li>
      <li>Display or share the QR code / participant link. The "Open participant" button opens this view in a new tab, without closing your dashboard.</li>
      <li>Participants answer from their phone.</li>
      <li>Track the number of participants and validated questionnaires.</li>
      <li>Move on to results once collection is sufficient or complete.</li>
    </ol>
    <p class="help-callout"><b>Remember:</b> participants only ever access the questionnaire — never configuration, nor the AI assistant.</p>
    <p class="help-callout"><b>If something goes wrong:</b> QR not reachable → check that the application's address is actually reachable from participants' phones.</p>`)},
  resultats:{title:L('Résultats / Diagnostic','Results / Diagnostic'),body:L(`
    <p><b>Capacité</b> = niveau obtenu à partir des réponses. <b>Consensus</b> = degré de convergence entre les réponses des participants.</p>
    <h3>Comment lire les deux ensemble ?</h3>
    <p class="help-callout">Capacité faible + consensus élevé → faiblesse largement partagée.</p>
    <p class="help-callout">Capacité faible + consensus faible → faiblesse possible mais perceptions divergentes.</p>
    <p class="help-callout">Capacité élevée + consensus élevé → force largement reconnue.</p>
    <p class="help-callout">Capacité élevée + consensus faible → situation globalement favorable, mais vécue différemment selon les participants.</p>
    <p>Si l’assistant IA est activé, il peut proposer une lecture de ces résultats (bouton « ✦ Analyser avec l’IA »).</p>
    <h3>Priorités et analyse</h3>
    <p>Les priorités sont choisies par les participants et le modérateur selon le processus EPC. Pour chaque priorité retenue, vous documentez un constat, puis des causes, conséquences et leviers.</p>
    <p>L’IA peut aider à reformuler le constat, préparer des questions, suggérer des hypothèses de causes, de conséquences, ou identifier des leviers.</p>
    <p class="help-callout"><b>À retenir :</b> une suggestion IA n’est jamais une cause validée. Elle doit être discutée et retenue explicitement par le groupe.</p>
    <p class="help-callout"><b>En cas de problème :</b> pas de résultats → vérifiez qu’au moins un questionnaire a été validé par un participant.</p>`,`
    <p><b>Capacity</b> = level obtained from responses. <b>Consensus</b> = degree of convergence between participants' responses.</p>
    <h3>How to read the two together?</h3>
    <p class="help-callout">Low capacity + high consensus → widely shared weakness.</p>
    <p class="help-callout">Low capacity + low consensus → possible weakness but diverging perceptions.</p>
    <p class="help-callout">High capacity + high consensus → widely recognised strength.</p>
    <p class="help-callout">High capacity + low consensus → overall favourable situation, but experienced differently across participants.</p>
    <p>If the AI assistant is enabled, it can suggest a reading of these results ("✦ Analyse with AI" button).</p>
    <h3>Priorities and analysis</h3>
    <p>Priorities are chosen by participants and the facilitator following the EPC process. For each priority retained, you document a finding, then causes, consequences and levers.</p>
    <p>AI can help rephrase the finding, prepare questions, suggest hypotheses for causes and consequences, or identify levers.</p>
    <p class="help-callout"><b>Remember:</b> an AI suggestion is never a validated cause. It must be discussed and explicitly retained by the group.</p>
    <p class="help-callout"><b>If something goes wrong:</b> no results → check that at least one questionnaire has been validated by a participant.</p>`)},
  recommandations:{title:L('Recommandations','Recommendations'),body:L(`
    <p>Cet écran construit la chaîne qui relie les résultats aux actions à mener :</p>
    <p class="help-callout">PRIORITÉ → CONSTAT → CAUSES → LEVIERS → RECOMMANDATIONS</p>
    <p>L’IA peut proposer des pistes de recommandations fondées sur les causes et leviers déjà retenus, mais le groupe et le modérateur conservent la validation finale.</p>
    <h3>Formations et plan d’action</h3>
    <p>Depuis cet écran, accédez aussi aux <b>besoins / thèmes de formation</b> (repris automatiquement des recommandations de catégorie Formation) et au <b>plan d’action</b> (tableau des recommandations retenues, avec responsable et échéance).</p>
    <p><b>Étape suivante :</b> Rapport final.</p>`,`
    <p>This screen builds the chain that links results to actions to be taken:</p>
    <p class="help-callout">PRIORITY → FINDING → CAUSES → LEVERS → RECOMMENDATIONS</p>
    <p>AI can suggest recommendation ideas based on causes and levers already retained, but the group and the facilitator keep final validation.</p>
    <h3>Training and action plan</h3>
    <p>From this screen, you can also access <b>training needs / themes</b> (automatically pulled from Training-category recommendations) and the <b>action plan</b> (table of retained recommendations, with an owner and a deadline).</p>
    <p><b>Next step:</b> Final report.</p>`)},
  rapport:{title:L('Rapport final','Final report'),body:L(`
    <p>Le rapport rassemble automatiquement : méthodologie, participation, résultats EPC, graphiques, priorités, analyses, recommandations, formations, plan d’action et annexes.</p>
    <p>Téléchargez-le en Word, Excel, ou PDF (impression du rapport web).</p>
    <h3>✦ Assistance IA au rapport</h3>
    <p>L’IA peut préparer une proposition de rédaction à partir des résultats et analyses déjà validés. Elle ne recalcule pas les résultats et ne doit pas inventer les informations manquantes. Vous pouvez retenir, modifier, régénérer ou ignorer chaque proposition.</p>
    <p class="help-callout"><b>DONNÉES EPC</b> → calculées automatiquement. <b>TEXTE IA</b> → proposition rédactionnelle soumise à votre validation.</p>`,`
    <p>The report automatically gathers: methodology, participation, EPC results, charts, priorities, analyses, recommendations, training, action plan and appendices.</p>
    <p>Download it as Word, Excel, or PDF (print of the web report).</p>
    <h3>✦ AI assistance for the report</h3>
    <p>AI can prepare a draft based on already-validated results and analyses. It does not recompute results and must not invent missing information. You can keep, edit, regenerate or ignore each suggestion.</p>
    <p class="help-callout"><b>EPC DATA</b> → computed automatically. <b>AI TEXT</b> → draft wording subject to your validation.</p>`)},
};}
function helpPanel(){
  let screens=HELP_SCREENS(),key=window.currentHelpKey||'home',screen=screens[key]||screens.home;
  let n=document.querySelector('#notice');if(!n){n=document.createElement('div');n.id='notice';document.body.appendChild(n)}
  n.className='help-modal';
  n.innerHTML=`<div>
    <h2>${L('Aide','Help')} — ${esc(screen.title)}</h2>
    <p class="text-meta">${L('Outil de diagnostic EPC / SENEVAL · le bouton « ? » ouvre toujours l’aide de l’écran où vous êtes.','EPC / SENEVAL diagnostic tool · the "?" button always opens the help for the screen you are on.')}</p>
    ${screen.body}
    <button class="secondary help-close" onclick="this.closest('.help-modal').remove()">${L('Fermer','Close')}</button>
  </div>`;
}
function shell(active,cycleStage,title,subtitle,sessionSummary){
  document.querySelector('.app-shell')?.classList.remove('participant-mode');
  window.currentHelpKey=active;
  if(sessionSummary!==undefined)window.currentSessionSummary=sessionSummary;
  document.querySelector('#sidebar').innerHTML=renderSidebar(active);
  document.querySelector('#topbar').innerHTML=renderTopbar(title,subtitle,cycleStage);
}
function gaugeCircle(pct,size=150){
  let r=size*.36,c=2*Math.PI*r,cx=size/2,cy=size/2,off=c*(1-Math.max(0,Math.min(100,pct))/100);
  return `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}"><circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--gray-100)" stroke-width="12"/><circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--accent-600)" stroke-width="12" stroke-linecap="round" stroke-dasharray="${c.toFixed(1)}" stroke-dashoffset="${off.toFixed(1)}" transform="rotate(-90 ${cx} ${cy})"/><text x="${cx}" y="${cy-3}" text-anchor="middle" class="gauge-value">${pct}<tspan class="gauge-suffix">%</tspan></text><text x="${cx}" y="${cy+20}" text-anchor="middle" class="gauge-label">${pct>=100?L('PRÊT','READY'):L('À COMPLÉTER','TO COMPLETE')}</text></svg>`;
}
function gaugeSemi(value,min,max,unset){
  let v=value??min,pct=unset?0:Math.max(0,Math.min(1,(v-min)/(max-min||1))),r=72,cx=90,cy=92;
  let ang=Math.PI-Math.PI*pct,x2=cx+r*Math.cos(ang),y2=cy-r*Math.sin(ang),largeArc=pct>0.5?1:0;
  return `<svg width="180" height="112" viewBox="0 0 180 112"><path d="M ${cx-r} ${cy} A ${r} ${r} 0 0 1 ${cx+r} ${cy}" fill="none" stroke="var(--gray-100)" stroke-width="14" stroke-linecap="round"/>${pct>0?`<path d="M ${cx-r} ${cy} A ${r} ${r} 0 ${largeArc} 1 ${x2} ${y2}" fill="none" stroke="var(--accent-600)" stroke-width="14" stroke-linecap="round"/>`:''}<text x="90" y="76" text-anchor="middle" font-size="${unset?18:30}" font-weight="800" fill="${unset?'var(--gray-400)':'var(--gray-900)'}">${unset?L('Non défini','Not set'):v}</text><text x="10" y="108" font-size="10" fill="var(--gray-400)" font-weight="700">${min}</text><text x="170" y="108" text-anchor="end" font-size="10" fill="var(--gray-400)" font-weight="700">${max}</text></svg>`;
}
function sessionStatusBadge(s,a){if(s.status==='closed')return /historique/i.test(s.name)?'<span class="badge badge-info">'+L('Historique','Archived')+'</span>':'<span class="badge badge-success">'+L('Terminé','Completed')+'</span>';if(/\btest\b/i.test(s.name))return '<span class="badge badge-neutral">'+L('Test','Test')+'</span>';if(!a||!a.participantCount)return '<span class="badge badge-neutral">'+L('Nouveau','New')+'</span>';return '<span class="badge badge-progress">'+L('En cours','In progress')+'</span>'}
function emptyState(title,text,btnLabel,btnAction){return `<div class="empty-state"><h3>${esc(title)}</h3><p>${esc(text||'')}</p>${btnLabel?`<button onclick="${btnAction}">${esc(btnLabel)}</button>`:''}</div>`}
const ICON_LAYERS='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></svg>';
const ICON_CLOCK='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3.2 2"/></svg>';
const ICON_CHECK='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="8.5"/><path d="M8.3 12.3l2.6 2.6 5-5.4"/></svg>';
const ICON_DOC='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M6 3.5h8l4 4V20a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V4.5a1 1 0 0 1 1-1z"/><path d="M14 3.5V8h4"/><path d="M8.5 12.5h7M8.5 15.5h7"/></svg>';
function templateStructureLabel(t){if(!t.domain_count)return '';let perDomain=t.indicator_count&&t.domain_count&&t.indicator_count%t.domain_count===0?t.indicator_count/t.domain_count:null;return perDomain!=null?`${t.domain_count} ${L('domaines','domains')} × ${perDomain} ${L('indicateurs','indicators')}`:`${t.domain_count} ${L('domaines','domains')} · ${t.indicator_count} ${L('indicateurs','indicators')}`}
function statCard(tone,icon,num,label){return `<div class="stat-card"><div class="stat-icon tone-${tone}">${icon}</div><div class="stat-body"><div class="stat-num">${num}</div><div class="stat-label">${esc(label)}</div></div></div>`}
function sessionRow(s,a){let target=s.expected_participants||(a&&a.participantCount);let pct=a&&target?Math.round(a.completedCount/target*100):0;let created=s.created_at?new Date(s.created_at).toLocaleDateString(getLang()==='en'?'en-GB':'fr-FR'):'';let code='MIS-'+s.id.slice(0,4).toUpperCase();return `<div class="session-row" onclick="moderator('${s.id}')"><div class="session-main"><div class="name">${esc(s.name)}</div><div class="meta"><span class="text-meta">${created}${created?' · ':''}${code}</span>${sessionStatusBadge(s,a)}<span>${a?a.participantCount+' participant'+(a.participantCount>1?'s':''):'—'}</span>${s.date?`<span>${esc(s.date)}</span>`:''}</div></div><div class="progress-wrap"><div class="progress"><span style="width:${pct}%"></span></div><div class="pct">${a&&target?pct+'%':'—'}</div></div><div class="row-action"><button class="ghost" onclick="event.stopPropagation();moderator('${s.id}')">${L('Ouvrir','Open')} →</button></div></div>`}
let homeShowAll=false;
async function home(){let summaries=await Promise.all(S.map(s=>api('/api/sessions/'+s.id+'/analysis').catch(()=>null)));let enriched=S.map((s,i)=>({s,a:summaries[i]}));let total=enriched.length;let done=enriched.filter(x=>x.s.status==='closed').length;let inProgress=enriched.filter(x=>x.s.status==='open'&&x.a&&x.a.participantCount>0).length;let mostRecent=enriched[0];let visible=homeShowAll?enriched:enriched.slice(0,5);app.innerHTML=`<div class="hero-lead"><h2>${L('Que souhaitez-vous faire ?','What would you like to do?')}</h2></div><div class="action-grid"><div class="action-card" onclick="newSession()"><div class="icon">＋</div><h3>${L('Nouveau diagnostic','New diagnostic')}</h3><p>${L('Créer un nouvel atelier de diagnostic','Create a new diagnostic workshop')}</p><button onclick="event.stopPropagation();newSession()">${L('Démarrer','Start')}</button></div>${mostRecent?`<div class="action-card" onclick="moderator('${mostRecent.s.id}')"><div class="icon">↻</div><h3>${L('Reprendre','Resume')}</h3><p>${esc(mostRecent.s.name)}<br><span class="text-meta">${mostRecent.s.created_at?new Date(mostRecent.s.created_at).toLocaleDateString(getLang()==='en'?'en-GB':'fr-FR')+' · ':''}MIS-${mostRecent.s.id.slice(0,4).toUpperCase()}</span><br>${sessionStatusBadge(mostRecent.s,mostRecent.a)} ${mostRecent.a?`· ${mostRecent.a.completedCount}/${mostRecent.a.participantCount} ${L('validés','validated')}`:''}</p><button class="secondary" onclick="event.stopPropagation();moderator('${mostRecent.s.id}')">${L('Continuer','Continue')}</button></div>`:''}</div><div class="stats-grid">${statCard('blue',ICON_LAYERS,total,L('Ateliers au total','Total workshops'))}${statCard('orange',ICON_CLOCK,inProgress,L('En cours','In progress'))}${statCard('green',ICON_CHECK,done,L('Terminés','Completed'))}${statCard('neutral',ICON_DOC,T.length,L('Modèles disponibles','Available models'))}</div><div class="card"><div class="section-header"><h2>${L('Missions récentes','Recent missions')}</h2>${enriched.length>5?`<button class="ghost" onclick="homeShowAll=!homeShowAll;home()">${homeShowAll?L('Réduire','Collapse'):L('Voir toutes les missions','View all missions')}</button>`:''}</div>${enriched.length?`<div class="session-list">${visible.map(({s,a})=>sessionRow(s,a)).join('')}</div>`:emptyState(L('Aucun diagnostic pour le moment','No diagnostic yet'),L('Créez votre premier atelier pour commencer.','Create your first workshop to get started.'),L('Nouveau diagnostic','New diagnostic'),'newSession()')}</div><div class="card"><div class="section-header"><h3>${L('Modèles &amp; questionnaires','Models &amp; questionnaires')}</h3></div>${T.length?T.map(t=>`<div class="row"><div style="flex:2;min-width:200px"><b>${esc(t.name)}</b><div class="text-meta">${L('Modèle disponible','Available model')} · v${t.version}${templateStructureLabel(t)?' · '+templateStructureLabel(t):''}</div></div><button class="ghost" onclick="newSession('${t.id}')">${L('Utiliser','Use')}</button><button class="ghost" onclick="dup('${t.id}')">${L('Dupliquer','Duplicate')}</button><button class="ghost" onclick="edit('${t.id}')">${L('Modifier','Edit')}</button></div>`).join(''):emptyState(L('Aucun modèle disponible','No model available'),L('Importez un questionnaire pour commencer.','Import a questionnaire to get started.'))}<div class="row" style="margin-top:.6rem"><button class="secondary" onclick="importer()">${L('Importer un questionnaire','Import a questionnaire')}</button><a href="/api/templates/matrix.xlsx"><button type="button" class="secondary">${L('Créer à partir d’un modèle Excel','Create from an Excel template')}</button></a><button class="ghost" onclick="models()">${L('Voir tous les modèles','View all models')}</button></div></div>`}
function createModel(){app.innerHTML=`<section class="card">${back()}<h2>${L('Nouveau questionnaire','New questionnaire')}</h2><form onsubmit="makeModel(event)"><label>${L('Nom du questionnaire','Questionnaire name')}<input name="name" required></label><h3>${L('Échelle de notation','Rating scale')}</h3>${[[5,L('Totalement d’accord','Strongly agree')],[4,L('D’accord','Agree')],[3,L('Neutre','Neutral')],[2,L('N’est pas d’accord','Disagree')],[1,L('Totalement en désaccord','Strongly disagree')]].map(x=>`<label>${x[0]}<input name="note${x[0]}" value="${x[1]}"></label>`).join('')}<button>${L('Enregistrer','Save')}</button></form></section>`};async function makeModel(e){e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),x=await api('/api/templates',{method:'POST',body:JSON.stringify({name:f.name})});window.model=await api('/api/templates/'+x.id);window.model.scale.labels={1:f.note1,2:f.note2,3:f.note3,4:f.note4,5:f.note5};await api('/api/templates/'+x.id,{method:'PUT',body:JSON.stringify({name:f.name,description:'',scale:window.model.scale,priority:window.model.priority})});edit(x.id)}
function models(){shell('questionnaire','config',L('Modèles & questionnaires','Models & questionnaires'),L('Bibliothèque des questionnaires disponibles','Library of available questionnaires'));app.innerHTML=`<section class="card">${back()}<h2>${L('Modèles &amp; paramètres','Models &amp; settings')}</h2>${T.map(t=>`<div class="row"><span><b>${esc(t.name)}</b> · v${t.version}${templateStructureLabel(t)?' · '+templateStructureLabel(t):''}</span><button onclick="edit('${t.id}')">${L('Ouvrir','Open')}</button><button class="secondary" onclick="dup('${t.id}')">${L('Dupliquer','Duplicate')}</button><a href="/api/templates/${t.id}/matrix.xlsx"><button type="button" class="secondary">${L('Exporter XLSX','Export XLSX')}</button></a><button class="danger" onclick="removeModel('${t.id}','${esc(t.name)}')">${L('Supprimer','Delete')}</button></div>`).join('')}</section>`};async function dup(id){let x=await api('/api/templates/'+id+'/clone',{method:'POST',body:'{}'});edit(x.id)};async function edit(id){window.model=await api('/api/templates/'+id);renderModel()};async function removeModel(id,name){if(!confirm(L('Supprimer le questionnaire "'+name+'" ?\n\nCette action supprimera cette configuration si elle n’est utilisée par aucune session.','Delete questionnaire "'+name+'"?\n\nThis will remove this configuration if it is not used by any session.')))return;try{await api('/api/templates/'+id,{method:'DELETE'});await load()}catch(e){if(e.message.includes('modèle de référence'))return notice(e.message);if(confirm(e.message+L('\n\nVoulez-vous le retirer de la liste des modèles tout en conservant les sessions historiques ?','\n\nDo you want to remove it from the model list while keeping historical sessions?'))){await api('/api/templates/'+id+'?force=1',{method:'DELETE'});await load()}}}
function autoGrow(el){if(!el)return;el.style.height='auto';el.style.height=el.scrollHeight+'px'}
function renderModel(){let t=window.model;let ready=t.domains.some(d=>d.active&&d.indicators.some(i=>i.active));let locked=!!t.is_canonical;shell('questionnaire','config',t.name,L('Structure du questionnaire','Questionnaire structure'));app.innerHTML=`<section class="card">${back()}<h2>${L('QUESTIONNAIRE','QUESTIONNAIRE')} : ${esc(t.name)}</h2>${locked?`<div class="scale-legend"><p><b>${L('Ce questionnaire est le modèle de référence protégé.','This questionnaire is the protected reference model.')}</b><br>${L('Il ne peut pas être modifié ni supprimé directement, afin de préserver les missions déjà réalisées avec lui. Pour préparer un nouveau questionnaire (par exemple avec moins d’indicateurs), créez d’abord votre propre copie modifiable.','It cannot be edited or deleted directly, to preserve missions already carried out with it. To prepare a new questionnaire (for example with fewer indicators), first create your own editable copy.')}</p><button onclick="dup('${t.id}')">${L('Dupliquer pour créer mon questionnaire','Duplicate to create my questionnaire')} →</button></div>`:''}<h3>${L('Échelle','Scale')}</h3>${Array.from({length:t.scale.max-t.scale.min+1},(_,k)=>t.scale.max-k).map(n=>`<div>${n} — ${esc(t.scale.labels?.[n]||'')}</div>`).join('')}<hr>${t.domains.map(d=>`<section class="domain" id="domain-${d.id}"><h3>${esc(d.label)}</h3>${locked?'':`<div class="row"><button class="secondary" onclick="editDomainForm('${d.id}')">${L('Modifier','Edit')}</button><button class="danger" onclick="delDomain('${d.id}')">${L('Supprimer','Delete')}</button><button class="secondary" onclick="moveDomain('${d.id}',-1)">↑</button><button class="secondary" onclick="moveDomain('${d.id}',1)">↓</button></div>`}${d.indicators.filter(i=>i.active).map((i,n)=>`<div class="indicator"><b>${n+1}. ${esc(i.label)}</b><br><form class="row" style="display:inline-flex;gap:.4rem;align-items:center" onsubmit="renameIndicatorReference(event,'${i.id}')"><span class="text-meta">${L('Référence','Reference')} :</span><input name="code" value="${esc(i.code)}" style="width:10rem" required><button class="secondary" type="submit">${L('Renommer','Rename')}</button></form>${locked?'':`<div class="row"><button class="secondary" onclick="indicator('${d.id}','${i.id}')">${L('Modifier','Edit')}</button><button class="danger" onclick="del('${i.id}')">${L('Supprimer','Delete')}</button><button class="secondary" onclick="moveIndicator('${i.id}',-1)">↑</button><button class="secondary" onclick="moveIndicator('${i.id}',1)">↓</button></div>`}</div>`).join('')}${locked?'':`<button onclick="indicator('${d.id}')">+ ${L('Ajouter une référence / question','Add a reference / question')}</button>`}</section>`).join('')}${locked?'':`<button onclick="editDomainForm()">+ ${L('Ajouter un domaine','Add a domain')}</button>`}<hr><button ${ready?'':'disabled'} onclick="newSession('${t.id}')">${L('Valider le questionnaire et démarrer un atelier','Validate the questionnaire and start a workshop')} →</button>${ready?'':`<p class="muted">${L('Ajoutez au moins un domaine avec une question pour démarrer un atelier.','Add at least one domain with a question to start a workshop.')}</p>`}</section>`}
