async function editKeepDomain(domainId){await edit(window.model.id);if(domainId)document.getElementById('domain-'+domainId)?.scrollIntoView({block:'start'})}
async function saveModel(e){e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),t=window.model,labels;try{labels=JSON.parse(f.labels||'{}')}catch(_){return alert(L('Les libellés doivent être un JSON valide.','Labels must be valid JSON.'))}let x=await api('/api/templates/'+t.id,{method:'PUT',body:JSON.stringify({name:f.name,description:f.description,scale:{type:'numeric',min:+f.min,max:+f.max,labels},priority:t.priority})});if(x.versionCreated)alert(L('Nouvelle version créée.','New version created.'));await edit(x.id)}
const DOMAIN_SUMMARY_MAX_WORDS=60;
function domainSummaryWordCount(text){return (text||'').trim()?(text||'').trim().split(/\s+/).length:0}
function updateDomainSummaryWordCount(el){let n=domainSummaryWordCount(el.value),c=document.querySelector('#domain-summary-wordcount');if(!c)return;c.textContent=n+' / '+DOMAIN_SUMMARY_MAX_WORDS+' '+L('mots','words');c.classList.toggle('over-limit',n>DOMAIN_SUMMARY_MAX_WORDS)}
function editDomainForm(id){let d=window.model.domains.find(x=>x.id===id)||{};app.innerHTML=`<section class="card"><button class="secondary" onclick="editKeepDomain('${id||''}')">← ${L('Retour','Back')}</button><h2>${id?L('Modifier le domaine','Edit domain'):L('Ajouter un domaine','Add a domain')}</h2><form onsubmit="saveDomain(event,'${id||''}')"><label>${L('Nom du domaine','Domain name')}<input name="label" required value="${esc(d.label||'')}"></label><label>${L('Présentation sommaire de la situation ou résultats des discussions (facultatif, ','Brief overview of the situation or discussion results (optional, ')}${DOMAIN_SUMMARY_MAX_WORDS} ${L('mots maximum)','words maximum)')}<textarea name="description" id="domain-summary-input" placeholder="${L('Affiché aux participants au début de ce domaine, s’il est renseigné…','Shown to participants at the start of this domain, if filled in…')}" oninput="autoGrow(this);updateDomainSummaryWordCount(this)" style="resize:none;overflow:hidden">${esc(d.description||'')}</textarea></label><p class="text-meta" id="domain-summary-wordcount">${domainSummaryWordCount(d.description||'')} / ${DOMAIN_SUMMARY_MAX_WORDS} ${L('mots','words')}</p><button class="secondary" type="button" onclick="editKeepDomain('${id||''}')">${L('Annuler','Cancel')}</button><button>${id?L('Enregistrer','Save'):L('Ajouter','Add')}</button></form></section>`;autoGrow(document.querySelector('#domain-summary-input'))};async function saveDomain(e,id){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(!f.label.trim())return alert(L('Veuillez donner un nom au domaine.','Please give the domain a name.'));if(domainSummaryWordCount(f.description)>DOMAIN_SUMMARY_MAX_WORDS)return notice(L('La présentation sommaire dépasse '+DOMAIN_SUMMARY_MAX_WORDS+' mots ('+domainSummaryWordCount(f.description)+'). Merci de la raccourcir avant d’enregistrer.','The brief overview exceeds '+DOMAIN_SUMMARY_MAX_WORDS+' words ('+domainSummaryWordCount(f.description)+'). Please shorten it before saving.'));let targetId=id;if(id){let d=window.model.domains.find(x=>x.id===id);await api('/api/domains/'+id,{method:'PUT',body:JSON.stringify({label:f.label,description:f.description,displayOrder:d.display_order,active:true})})}else{let nd=await api('/api/templates/'+window.model.id+'/domains',{method:'POST',body:JSON.stringify({label:f.label,description:f.description})});targetId=nd.id}editKeepDomain(targetId)};async function delDomain(id){if(!confirm(L('Supprimer ce domaine et toutes ses questions ?','Delete this domain and all its questions?')))return;try{await api('/api/domains/'+id,{method:'DELETE'})}catch(e){if(!confirm(e.message+L('\n\nDésactiver ce domaine à la place (conserve l’historique) ?','\n\nDeactivate this domain instead (keeps history)?')))return;let d=window.model.domains.find(x=>x.id===id);await api('/api/domains/'+id,{method:'PUT',body:JSON.stringify({label:d.label,description:d.description,displayOrder:d.display_order,active:false})})}edit(window.model.id)}
// Proposition automatique de Référence courte (mission :8810, demande Mouhamed BA)
// - miroir exact de generate_indicator_reference()/propose_indicator_reference()
// cote Python (app.py), pour une proposition instantanee sans appel reseau ni
// dependance IA. L'unicite dans le domaine est verifiee localement contre
// window.model, deja charge par renderModel().
const INDICATOR_REFERENCE_STOPWORDS=new Set(['nous','notre','nos','vous','vos','votre','leur','leurs','on','il','ils','elle','elles','le','la','les','l','de','des','du','d','et','en','au','aux','à','a','ce','cet','cette','ces','un','une','pour','que','qui','dans','avec','sur','par','est','sont','ont','avons','avez','être','avoir','tout','tous','toute','toutes','très','plus','moins','bien','mal','comme','régulièrement','systématiquement','activement','efficacement','généralement','directement','constamment','correctement','également','notamment','ainsi','donc','offrons','offre','offrent','utilisons','utilise','utilisent','procédons','modifions','modifie','examinons','examine','engageons','engage','établissons','établit','disposons','dispose','reconnaissons','reconnait','impliquons','implique','faisons','fait','accordons','accorde','obtenons','obtient','participent','participe','contribuent','contribue','favorise','favorisent','encourage','encouragent','améliore','améliorent','reflète','reflètent','montre','montrent','permettent','permet','existe','existent','appropriée','appropriées','approprié','appropriés']);
function significantReferenceWords(label){let words=(label||'').trim().match(/[A-Za-zÀ-ÿŒœÆæ]+(?:-[A-Za-zÀ-ÿŒœÆæ]+)*/g)||[];let sig=words.filter(w=>!INDICATOR_REFERENCE_STOPWORDS.has(w.toLowerCase().replace(/[’']/g,'')));return sig.length?sig:words}
function referencePhrase(words){if(!words.length)return '';let phrase=words.join(' ');return phrase.charAt(0).toUpperCase()+phrase.slice(1)}
const INDICATOR_REFERENCE_MAX_WORDS=2;
function generateIndicatorReference(label){return referencePhrase(significantReferenceWords(label).slice(0,INDICATOR_REFERENCE_MAX_WORDS))}
function indicatorReferenceConflicts(code,domainId,excludeId){let d=(window.model?.domains||[]).find(x=>x.id===domainId);if(!d||!code)return false;return d.indicators.some(i=>i.active!==false&&i.code===code&&i.id!==excludeId)}
function proposeIndicatorReference(label,domainId,excludeId){let words=significantReferenceWords(label);let base=referencePhrase(words.slice(0,INDICATOR_REFERENCE_MAX_WORDS));if(!base||!indicatorReferenceConflicts(base,domainId,excludeId))return base;if(words.length>INDICATOR_REFERENCE_MAX_WORDS){let extended=referencePhrase(words.slice(0,INDICATOR_REFERENCE_MAX_WORDS+1));if(!indicatorReferenceConflicts(extended,domainId,excludeId))return extended}return base}
function markIndicatorReferenceTouched(){window.__indicatorRefTouched=true}
function onIndicatorLabelBlur(did,iid){if(window.__indicatorRefTouched)return;let label=document.querySelector('#indicator-label-input')?.value;if(!label||!label.trim())return;let proposal=proposeIndicatorReference(label,did,iid||null);let codeInput=document.querySelector('#indicator-code-input');if(codeInput&&proposal)codeInput.value=proposal}
function regenerateIndicatorReference(did,iid){let label=document.querySelector('#indicator-label-input')?.value;if(!label||!label.trim())return notice(L('Saisissez d’abord l’énoncé de la question.','First enter the question wording.'));let proposal=proposeIndicatorReference(label,did,iid||null);document.querySelector('#indicator-code-input').value=proposal}
function indicator(did,iid){let i=window.model.domains.flatMap(d=>d.indicators).find(x=>x.id===iid)||{};window.__indicatorRefTouched=!!iid;app.innerHTML=`<section class="card"><button class="secondary" onclick="editKeepDomain('${did}')">← ${L('Retour','Back')}</button><h2>${iid?L('Modifier la question','Edit question'):L('Ajouter une référence / question','Add a reference / question')}</h2><form onsubmit="saveIndicator(event,'${iid||''}')"><input type="hidden" name="domainId" value="${did}"><label>${L('Question / indicateur','Question / indicator')}<textarea name="label" id="indicator-label-input" required onblur="onIndicatorLabelBlur('${did}','${iid||''}')">${esc(i.label||'')}</textarea></label><label>${L('Référence (courte, 2 mots maximum, sert d’étiquette sous les histogrammes)','Reference (short, 2 words maximum, used as a label under histograms)')}<input name="code" id="indicator-code-input" required value="${esc(i.code||'')}" oninput="markIndicatorReferenceTouched()"></label><p class="text-meta" style="margin-top:-.4rem">${L('Référence générée automatiquement (2 mots maximum), modifiable si nécessaire.','Reference generated automatically (2 words maximum), editable if needed.')}</p><div class="row" style="margin-bottom:.6rem"><button type="button" class="ghost" onclick="regenerateIndicatorReference('${did}','${iid||''}')">↻ ${L('Regénérer la référence','Regenerate the reference')}</button></div><button class="secondary" type="button" onclick="editKeepDomain('${did}')">${L('Annuler','Cancel')}</button><button>${iid?L('Enregistrer','Save'):L('Ajouter','Add')}</button></form></section>`};async function saveIndicator(e,id){e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),i=window.model.domains.flatMap(d=>d.indicators).find(x=>x.id===id)||{};if(!f.code.trim()||!f.label.trim())return notice(L('Veuillez renseigner la référence et la question.','Please fill in the reference and the question.'));let d={domainId:f.domainId,code:f.code,label:f.label,description:i.description||'',responseType:'numeric',required:true,active:true,displayOrder:i.display_order||1};if(id)await api('/api/indicators/'+id,{method:'PUT',body:JSON.stringify(d)});else await api('/api/domains/'+f.domainId+'/indicators',{method:'POST',body:JSON.stringify(d)});editKeepDomain(f.domainId)};async function del(id){if(!confirm(L('Supprimer cette question ?','Delete this question?')))return;let d0=window.model.domains.find(x=>x.indicators.some(y=>y.id===id)),domainId=d0&&d0.id;try{await api('/api/indicators/'+id,{method:'DELETE'})}catch(e){if(!confirm(e.message+L('\n\nDésactiver cette question à la place (conserve l’historique) ?','\n\nDeactivate this question instead (keeps history)?')))return;let d=window.model.domains.find(x=>x.indicators.some(y=>y.id===id)),i=d.indicators.find(y=>y.id===id);await api('/api/indicators/'+id,{method:'PUT',body:JSON.stringify({domainId:d.id,code:i.code,label:i.label,description:i.description,responseType:i.response_type,required:i.required,active:false,displayOrder:i.display_order})})}editKeepDomain(domainId)}
async function renameIndicatorReference(e,id){e.preventDefault();let code=(new FormData(e.target).get('code')||'').trim();if(!code)return notice(L('La référence est obligatoire.','The reference is required.'));let d=window.model.domains.find(x=>x.indicators.some(y=>y.id===id));try{await api('/api/indicators/'+id+'/reference',{method:'PUT',body:JSON.stringify({code})})}catch(err){return notice(err.message)}editKeepDomain(d&&d.id)}
async function moveDomain(id,delta){let a=window.model.domains,b=a.findIndex(x=>x.id===id),o=a[b+delta];if(!o)return;let x=a[b];await api('/api/domains/'+x.id,{method:'PUT',body:JSON.stringify({label:x.label,description:x.description,displayOrder:o.display_order,active:true})});await api('/api/domains/'+o.id,{method:'PUT',body:JSON.stringify({label:o.label,description:o.description,displayOrder:x.display_order,active:true})});editKeepDomain(id)}
async function moveIndicator(id,delta){let d=window.model.domains.find(x=>x.indicators.some(i=>i.id===id)),a=d.indicators.filter(i=>i.active),b=a.findIndex(x=>x.id===id),o=a[b+delta];if(!o)return;let x=a[b],put=i=>api('/api/indicators/'+i.id,{method:'PUT',body:JSON.stringify({domainId:d.id,code:i.code,label:i.label,description:i.description,responseType:i.response_type,required:i.required,active:true,displayOrder:i.display_order})});let xo=x.display_order;x.display_order=o.display_order;o.display_order=xo;await put(x);await put(o);editKeepDomain(d.id)}
function importer(){app.innerHTML=`<section class="card">${back()}<h2>${L('Importer un questionnaire','Import a questionnaire')}</h2><form onsubmit="up(event)"><input type="file" name="f" accept=".xlsx" required><button>${L('Contrôler et prévisualiser','Check and preview')}</button></form></section>`};async function up(e){e.preventDefault();let r=await fetch('/api/templates/import/preview',{method:'POST',body:new FormData(e.target)}),x=await r.json();if(!r.ok)return alert(x.error);app.innerHTML=`<section class="card">${back()}<h2>${L('Aperçu','Preview')}</h2>${x.errors.length?`<p class="error">${x.errors.join('<br>')}</p>`:`<p class="ok">${x.rows} ${L('indicateurs valides ; rien n’est enregistré.','valid indicators; nothing is saved.')}</p>`}<button ${x.errors.length?'disabled':''} onclick="confirmImport('${x.token}')">${L('Valider l’import','Confirm import')}</button></section>`};async function confirmImport(token){let x=await api('/api/templates/import/confirm',{method:'POST',body:JSON.stringify({token})});edit(x.id)}
function newSession(selectedId){shell('home','',L('Nouveau diagnostic','New diagnostic'),L('Donnez un nom à votre mission pour commencer','Give your mission a name to get started'));app.innerHTML=`<section class="card">${back()}<h2>${L('Nouveau diagnostic','New diagnostic')}</h2><form onsubmit="makeSession(event,'${selectedId||''}')"><label>${L('Objet de la mission','Mission subject')}<input name="name" required autofocus placeholder="${L('Ex : Atelier Dakar','E.g.: Dakar workshop')}"></label><p class="text-meta">${selectedId?'':L('Le questionnaire EPC / SENEVAL est utilisé par défaut — vous pourrez le changer ou en créer un nouveau depuis la Configuration, à l’étape suivante.','The EPC / SENEVAL questionnaire is used by default — you will be able to change it or create a new one from Configuration, at the next step.')}</p><button>${L('Créer la mission','Create the mission')} →</button></form></section>`};async function makeSession(e,selectedId){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));let templateId=selectedId||T.find(t=>t.is_canonical)?.id||T[0]?.id;if(!templateId)return notice(L('Aucun questionnaire disponible pour démarrer. Créez-en un depuis Modèles & questionnaires.','No questionnaire available to start. Create one from Models & questionnaires.'));let x=await api('/api/sessions',{method:'POST',body:JSON.stringify({name:f.name,templateId})});configuration(x.id)}

async function configuration(id){
  let list=await api('/api/sessions'),s=list.find(x=>x.id===id);
  if(!s)return notice(L('Atelier introuvable.','Workshop not found.'));
  let t=await api('/api/templates/'+s.template_id);
  let a=await api('/api/sessions/'+id+'/analysis').catch(()=>null);
  window.configHasData=!!(a&&a.participantCount>0);
  let aiCfg=await api('/api/ai/config').catch(()=>({enabled:false,provider:null,model:null,keyConfigured:false,providers:{}}));
  window.aiCfg=aiCfg;
  window.scaleLocked=!!(a&&a.global&&a.global.responses>0);
  window.currentSessionId=id;
  let domains=t.domains.filter(d=>d.active);
  let totalInd=domains.reduce((n,d)=>n+d.indicators.filter(i=>i.active).length,0);
  let expected=s.expected_participants,sliderVal=expected||20;
  window.scaleDraft={min:+t.scale.min,max:+t.scale.max,labels:{...(t.scale.labels||{})}};
  let steps=[
    {label:L('Mission','Mission'),sub:L('Défini','Defined'),done:!!(s.name&&s.location)},
    {label:L('Questionnaire','Questionnaire'),sub:L('Sélectionné','Selected'),done:domains.length>0&&totalInd>0},
    {label:L('Participants','Participants'),sub:L('Paramétrés','Set'),done:!!s.expected_participants},
    {label:L('Vérification','Verification'),sub:L('En attente','Pending'),done:false},
  ];
  let doneCount=steps.filter(x=>x.done).length,pct=Math.round(doneCount/steps.length*100);
  let ready=domains.length>0&&totalInd>0;
  shell('config','config',L('CONFIGURATION DE LA MISSION','MISSION SETUP'),L('Paramétrez votre mission avant de lancer la collecte','Set up your mission before launching collection'),{id,name:s.name,location:s.location,date:s.date,pct,statusLabel:L('Préparation','Preparation')});
  app.innerHTML=`${window.configHasData?`<div class="card" style="border-left:4px solid var(--orange-600);background:var(--orange-50);margin-bottom:1rem"><b>⚠ ${L('Cet atelier contient déjà des données réelles','This workshop already contains real data')}</b><p class="muted small" style="margin:.3rem 0 0">${a.participantCount} participant${a.participantCount>1?'s':''} · ${a.completedCount} ${L('questionnaire'+(a.completedCount>1?'s':'')+' validé'+(a.completedCount>1?'s':''),'validated questionnaire'+(a.completedCount>1?'s':''))}. ${L('Modifier le nom ci-dessous renomme cet atelier existant — cela ne crée pas un nouvel atelier vierge. Pour démarrer un diagnostic entièrement neuf, utilisez « Nouveau diagnostic » depuis l’accueil.','Changing the name below renames this existing workshop — it does not create a new blank workshop. To start an entirely new diagnostic, use "New diagnostic" from the home screen.')}</p></div>`:''}<div class="cfg-grid-71"><div class="card"><div class="row" style="align-items:center;gap:1.6rem;flex-wrap:wrap">${gaugeCircle(pct)}<div style="flex:1;min-width:240px"><h2>${L('Préparation de la mission','Mission preparation')}</h2><p class="muted small">${L('Vérifiez et ajustez les paramètres de votre atelier avant d’ouvrir la collecte.','Check and adjust your workshop’s settings before opening collection.')}</p><div class="hstepper">${steps.map((st,i)=>`<div class="hstep ${st.done?'done':((i===0||steps[i-1].done)&&!st.done?'current':'')}"><span class="circle">${st.done?'✓':i+1}</span><span class="hlabel">${st.label}<br>${st.sub}</span></div>`).join('')}</div></div></div></div><div class="card"><h3>${L('Aperçu de votre mission','Overview of your mission')}</h3><div class="overview-list"><div class="ov-row"><span class="ov-label">${L('Objet de la mission','Mission subject')}</span><span class="ov-value">${esc(s.name)}</span></div><div class="ov-row"><span class="ov-label">${L('Questionnaire','Questionnaire')}</span><span class="ov-value">${esc(t.name)} v${t.version}</span></div><div class="ov-row"><span class="ov-label">${L('Domaines','Domains')}</span><span class="ov-value">${domains.length}</span></div><div class="ov-row"><span class="ov-label">${L('Indicateurs','Indicators')}</span><span class="ov-value">${totalInd}</span></div><div class="ov-row"><span class="ov-label">${L('Participants prévus','Expected participants')}</span><span class="ov-value">${s.expected_participants||'—'}</span></div><div class="ov-row"><span class="ov-label">${L('Échelle de notation','Rating scale')}</span><span class="ov-value">${t.scale.min} ${L('à','to')} ${t.scale.max}</span></div></div></div></div><div class="cfg-grid-3"><div class="card"><div class="section-header"><h3>1 · ${L('Informations de la mission','Mission information')}</h3></div><form onsubmit="saveConfigInfo(event,'${id}')"><label>${L('Objet de la mission','Mission subject')}<input name="name" required value="${esc(s.name)}"></label><div class="row row-fields"><label>${L('Lieu','Location')}<input name="location" value="${esc(s.location||'')}"></label><label>${L('Date','Date')}<input name="date" type="date" value="${esc(s.date||'')}"></label></div><label>${L('Description (optionnelle)','Description (optional)')}<textarea name="description">${esc(s.description||'')}</textarea></label><button class="secondary" type="submit">${L('Enregistrer','Save')}</button></form></div><div class="card" style="text-align:center"><div class="section-header" style="text-align:left"><h3>2 · ${L('Participants','Participants')}</h3></div><div id="participants-gauge">${gaugeSemi(sliderVal,1,100,!expected)}</div><input id="participants-range" type="range" min="1" max="100" value="${sliderVal}" style="width:100%" oninput="updateParticipantsGauge(this.value)"><input id="participants-number" type="number" min="1" placeholder="${L('Non défini','Not set')}" value="${expected||''}" style="width:100%;margin-top:.5rem" onchange="document.querySelector('#participants-range').value=this.value||20;updateParticipantsGauge(this.value||20)"><p class="text-meta" style="margin-top:.6rem;text-align:left">${L('Ce nombre sert de référence pour les analyses. Le nombre réel de participants reste calculé à partir des données collectées.','This number is used as a reference for analyses. The actual number of participants is still calculated from collected data.')}</p><button class="secondary block" onclick="saveExpectedParticipants('${id}')">${L('Enregistrer','Save')}</button></div><div class="card"><div class="section-header"><h3>3 · ${L('Structure du questionnaire','Questionnaire structure')}</h3></div><div class="pill-row"><div class="stat-pill"><div class="pill-ic">${ICON_LAYERS}</div><div><b>${domains.length}</b><span>${L('Domaines','Domains')}</span></div></div><div class="stat-pill"><div class="pill-ic">${ICON_DOC}</div><div><b>${totalInd}</b><span>${L('Indicateurs','Indicators')}</span></div></div></div><p class="text-meta">${L('Répartition par domaine','Breakdown by domain')}</p>${domains.map((d,i)=>{let n=d.indicators.filter(x=>x.active).length,max=Math.max(...domains.map(x=>x.indicators.filter(y=>y.active).length),1);return `<div class="domain-bar-row"><span class="db-label">${i+1}. ${esc(d.label)}</span><span class="db-track"><span class="db-fill" style="width:${n/max*100}%;background:${DOMAIN_COLORS[i%7]}"></span></span><span class="db-count">${n}</span></div>`}).join('')}<button class="secondary block" style="margin-top:.8rem" onclick="edit('${t.id}')">${L('Voir / Modifier le questionnaire','View / Edit the questionnaire')} →</button>${scaleLocked?`<p class="text-meta" style="margin-top:.6rem">${L('Cet atelier a déjà des réponses : le questionnaire ne peut plus être changé ou recréé.','This workshop already has responses: the questionnaire can no longer be changed or recreated.')}</p>`:`<div class="row" style="margin-top:.5rem;gap:.5rem;flex-wrap:wrap"><button class="ghost" onclick="pickQuestionnaire('${id}')">🔁 ${L('Changer de questionnaire','Change questionnaire')}</button><button class="ghost" onclick="createQuestionnaireForSession('${id}')">+ ${L('Nouveau questionnaire','New questionnaire')}</button></div>`}</div></div><div class="cfg-grid-71"><div class="card"><div class="section-header"><h3>4 · ${L('Échelle de notation','Rating scale')}</h3></div>${scaleLocked?`<p class="muted small">${L('Cet atelier a déjà des réponses enregistrées. L’échelle de notation ne peut plus être modifiée : la changer invaliderait ces réponses.','This workshop already has saved responses. The rating scale can no longer be edited: changing it would invalidate those responses.')}</p><div class="scale-cards" style="--scale-cols:${scaleDraft.max-scaleDraft.min+1}">${Array.from({length:scaleDraft.max-scaleDraft.min+1},(_,k)=>{let v=scaleDraft.min+k,tone=scaleTone(k+1,scaleDraft.max-scaleDraft.min+1);return `<div class="scale-card sc-${tone}"><div class="sc-num">${v}</div><div class="sc-label">${esc(scaleDraft.labels?.[v]||'')}</div><div class="sc-emoji">${SCALE_EMOJI[tone-1]}</div></div>`}).join('')}</div>`:`<p class="muted small">${L('Les participants noteront chaque indicateur selon l’échelle suivante. Renommez les niveaux ou ajustez leur nombre selon vos besoins.','Participants will rate each indicator using the following scale. Rename the levels or adjust their number as needed.')}</p><form onsubmit="saveScale(event,'${id}','${t.id}')"><div class="scale-cards" id="scale-cards" style="--scale-cols:${scaleDraft.max-scaleDraft.min+1}">${renderScaleCards(scaleDraft.min,scaleDraft.max,scaleDraft.labels)}</div><div class="row" style="margin-top:.7rem;flex-wrap:wrap;gap:.5rem"><button type="button" class="secondary" onclick="removeScaleLevel()">− ${L('Retirer un niveau','Remove a level')}</button><button type="button" class="secondary" onclick="addScaleLevel()">+ ${L('Ajouter un niveau','Add a level')}</button><button class="secondary" type="submit" style="margin-left:auto">${L('Enregistrer l’échelle','Save the scale')}</button></div></form>`}</div><div class="card launch-block"><div class="launch-ic">🛡️</div><h3>${L('Prêt à ouvrir la collecte ?','Ready to open collection?')}</h3><p class="muted small">${L('Vérifiez que tous les paramètres sont corrects puis ouvrez la collecte pour les participants.','Check that all settings are correct, then open collection for participants.')}</p><button class="primary-lg" onclick="launchCollecte('${id}',${ready})">🚀 ${L('Ouvrir la collecte','Open collection')}</button><button class="secondary" onclick="preview('${id}')">👁 ${L('Aperçu du questionnaire','Questionnaire preview')}</button></div></div>${aiConfigCardHtml(aiCfg)}<p class="text-meta" style="margin-top:.5rem;display:flex;justify-content:space-between;flex-wrap:wrap;gap:.4rem"><span>${L('Vous pourrez ajuster certains paramètres pendant l’atelier. Toute modification du questionnaire sera versionnée.','You will be able to adjust some settings during the workshop. Any questionnaire change will be versioned.')}</span><span>${L('Dernière sauvegarde','Last saved')} : ${new Date().toLocaleString(getLang()==='en'?'en-GB':'fr-FR')}</span></p>`;
}
const SCALE_EMOJI=['😞','🙁','😐','🙂','😄'];
function scaleTone(i,count){return count<=1?3:Math.round(1+(i-1)/(count-1)*4)}
function renderScaleCards(min,max,labels){let n=max-min+1;return Array.from({length:n},(_,k)=>{let v=min+k,tone=scaleTone(k+1,n);return `<div class="scale-card sc-${tone}"><div class="sc-num">${v}</div><input class="sc-label-input" data-level="${v}" value="${esc(labels?.[v]??labels?.[String(v)]??'')}" placeholder="${L('Libellé du niveau','Label for level')} ${v}"><div class="sc-emoji">${SCALE_EMOJI[tone-1]}</div></div>`}).join('')}
function refreshScaleCards(){let el=document.querySelector('#scale-cards');el.style.setProperty('--scale-cols',scaleDraft.max-scaleDraft.min+1);el.innerHTML=renderScaleCards(scaleDraft.min,scaleDraft.max,scaleDraft.labels)}
function collectScaleLabels(){let labels={};document.querySelectorAll('.sc-label-input').forEach(inp=>{labels[inp.dataset.level]=inp.value});return labels}
function addScaleLevel(){if(scaleDraft.max-scaleDraft.min+1>=9)return notice(L('Le nombre maximum de niveaux est 9.','The maximum number of levels is 9.'));scaleDraft.labels=collectScaleLabels();scaleDraft.max+=1;refreshScaleCards()}
function removeScaleLevel(){if(scaleDraft.max-scaleDraft.min+1<=2)return notice(L('Il faut conserver au moins 2 niveaux.','At least 2 levels must be kept.'));scaleDraft.labels=collectScaleLabels();scaleDraft.max-=1;delete scaleDraft.labels[scaleDraft.max+1];refreshScaleCards()}
async function saveScale(e,id,tid){e.preventDefault();if(window.scaleLocked)return notice(L('Impossible de modifier l’échelle : cet atelier a déjà des réponses enregistrées.','Cannot edit the scale: this workshop already has saved responses.'));let labels=collectScaleLabels();if(Object.values(labels).some(v=>!v.trim()))return notice(L('Veuillez renseigner un libellé pour chaque niveau.','Please fill in a label for each level.'));let x=await api('/api/templates/'+tid,{method:'PUT',body:JSON.stringify({scale:{type:'numeric',min:scaleDraft.min,max:scaleDraft.max,labels}})});if(x.id!==tid){let cur=(await api('/api/sessions')).find(s=>s.id===id);await api('/api/sessions/'+id,{method:'PUT',body:JSON.stringify({name:cur.name,organization:cur.organization,location:cur.location,date:cur.date,description:cur.description,expectedParticipants:cur.expected_participants,templateId:x.id})})}notice(L('Échelle de notation enregistrée.','Rating scale saved.'));configuration(id)}
async function pickQuestionnaire(id){let list=await api('/api/templates');shell('config','config',L('Changer de questionnaire','Change questionnaire'),L('Choisissez le questionnaire à utiliser pour cet atelier','Choose the questionnaire to use for this workshop'));app.innerHTML=`<section class="card"><button class="secondary" onclick="configuration('${id}')">← ${L('Retour à la configuration','Back to configuration')}</button><h2>${L('Changer de questionnaire','Change questionnaire')}</h2><form onsubmit="applyQuestionnaire(event,'${id}')"><label>${L('Questionnaire','Questionnaire')}<select name="templateId">${list.map(t=>`<option value="${t.id}">${esc(t.name)} v${t.version}</option>`).join('')}</select></label><p class="text-meta">${L('Changer de questionnaire remplace les domaines, indicateurs et l’échelle utilisés par cet atelier.','Changing questionnaire replaces the domains, indicators and scale used by this workshop.')}</p><button>${L('Utiliser ce questionnaire','Use this questionnaire')} →</button></form></section>`}
async function applyQuestionnaire(e,id){e.preventDefault();if(window.scaleLocked)return notice(L('Impossible de changer de questionnaire : cet atelier a déjà des réponses enregistrées.','Cannot change questionnaire: this workshop already has saved responses.'));let f=Object.fromEntries(new FormData(e.target));let cur=(await api('/api/sessions')).find(s=>s.id===id);await api('/api/sessions/'+id,{method:'PUT',body:JSON.stringify({name:cur.name,organization:cur.organization,location:cur.location,date:cur.date,description:cur.description,expectedParticipants:cur.expected_participants,templateId:f.templateId})});notice(L('Questionnaire mis à jour.','Questionnaire updated.'));configuration(id)}
function createQuestionnaireForSession(id){shell('config','config',L('Nouveau questionnaire','New questionnaire'),L('Créer un questionnaire vierge pour cet atelier','Create a blank questionnaire for this workshop'));app.innerHTML=`<section class="card"><button class="secondary" onclick="configuration('${id}')">← ${L('Retour à la configuration','Back to configuration')}</button><h2>${L('Nouveau questionnaire','New questionnaire')}</h2><form onsubmit="makeQuestionnaireForSession(event,'${id}')"><label>${L('Nom du questionnaire','Questionnaire name')}<input name="name" required autofocus placeholder="${L('Ex : Diagnostic EPC / Atelier Dakar','E.g.: EPC diagnostic / Dakar workshop')}"></label><p class="text-meta">${L('Vous pourrez ensuite ajouter des domaines et des indicateurs, ou importer une matrice XLSX.','You will then be able to add domains and indicators, or import an XLSX matrix.')}</p><button>${L('Créer','Create')} →</button></form></section>`}
async function makeQuestionnaireForSession(e,id){e.preventDefault();if(window.scaleLocked)return notice(L('Impossible de créer un nouveau questionnaire : cet atelier a déjà des réponses enregistrées.','Cannot create a new questionnaire: this workshop already has saved responses.'));let f=Object.fromEntries(new FormData(e.target));let x=await api('/api/templates',{method:'POST',body:JSON.stringify({name:f.name})});let cur=(await api('/api/sessions')).find(s=>s.id===id);await api('/api/sessions/'+id,{method:'PUT',body:JSON.stringify({name:cur.name,organization:cur.organization,location:cur.location,date:cur.date,description:cur.description,expectedParticipants:cur.expected_participants,templateId:x.id})});notice(L('Nouveau questionnaire créé et associé à l’atelier. Ajoutez vos domaines et indicateurs.','New questionnaire created and linked to the workshop. Add your domains and indicators.'));edit(x.id)}
function updateParticipantsGauge(v){document.querySelector('#participants-gauge').innerHTML=gaugeSemi(+v,1,100,false);document.querySelector('#participants-number').value=v}
function aiConfigCardHtml(aiCfg){
  let providers=aiCfg.providers||{},curProvider=aiCfg.provider||Object.keys(providers)[0]||'',models=(providers[curProvider]||{}).models||[];
  return `<div class="cfg-grid-71"><div class="card"><div class="section-header"><h3>5 · ${L('Assistant IA','AI assistant')}</h3></div><p class="muted small">${L('L’assistant IA est facultatif. EPC / SENEVAL fonctionne intégralement sans intelligence artificielle.','The AI assistant is optional. EPC / SENEVAL works fully without artificial intelligence.')}</p><form onsubmit="saveAiConfig(event)"><label class="row" style="align-items:center;gap:.5rem"><input type="checkbox" name="enabled" style="width:auto" ${aiCfg.enabled?'checked':''} onchange="document.querySelector('#ai-fields').style.display=this.checked?'':'none'"> ${L('Activer l’assistant IA','Enable the AI assistant')}</label><div id="ai-fields" style="${aiCfg.enabled?'':'display:none'};margin-top:.6rem"><div class="row row-fields"><label>${L('Fournisseur IA','AI provider')} <span id="ai-provider-badge" class="ai-badge" data-pricing="${esc((providers[curProvider]||{}).pricing||'')}">${esc((providers[curProvider]||{}).pricing||'')}</span><select name="provider" id="ai-provider-select" onchange="updateAiModelOptions()">${Object.entries(providers).map(([k,v])=>`<option value="${k}" ${k===curProvider?'selected':''}>${esc(v.label)} — ${v.pricing}</option>`).join('')}</select></label><label>${L('Modèle','Model')}<select name="model" id="ai-model-select">${models.map(([mid,mlabel])=>`<option value="${esc(mid)}" ${mid===aiCfg.model?'selected':''}>${esc(mlabel)} (${esc(mid)})</option>`).join('')}</select></label></div><label>${L('Clé API','API key')}<div class="row" style="gap:.4rem"><input type="password" name="apiKey" id="ai-key-input" placeholder="${aiCfg.keyConfigured?L('•••••••••••••••••••• (déjà configurée — laisser vide pour la conserver)','•••••••••••••••••••• (already set — leave empty to keep it)'):L('Collez votre clé API ici','Paste your API key here')}" style="flex:1"><button type="button" class="secondary" onclick="toggleAiKeyVisibility()">👁</button><button type="button" class="secondary" onclick="aiKeyHelp()">?</button></div></label><div class="row" style="margin-top:.5rem;gap:.5rem;flex-wrap:wrap"><button class="secondary" type="submit">${L('Enregistrer','Save')}</button><button class="secondary" type="button" onclick="testAiConnection()">${L('Tester l’assistant IA','Test the AI assistant')}</button></div><p id="ai-test-status" class="text-meta" style="margin-top:.5rem"></p></div></form></div></div>`;
}
async function saveAiConfig(e){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));let body={enabled:!!f.enabled,provider:f.provider,model:f.model};if(f.apiKey)body.apiKey=f.apiKey;await api('/api/ai/config',{method:'PUT',body:JSON.stringify(body)});notice(L('Configuration de l’assistant IA enregistrée.','AI assistant configuration saved.'));configuration(window.currentSessionId)}
async function testAiConnection(){let status=document.querySelector('#ai-test-status');status.textContent=L('Test en cours…','Testing…');status.style.color='';try{let r=await api('/api/ai/test',{method:'POST',body:'{}'});if(r.ok){status.textContent=`✓ ${L('Assistant IA opérationnel','AI assistant operational')} — ${r.provider} · ${r.model} · ${r.latencyMs} ms`;status.style.color='var(--green-700)'}else{status.textContent='⚠ '+r.reason;status.style.color='var(--red-600)'}}catch(e){status.textContent='⚠ '+e.message;status.style.color='var(--red-600)'}}
function toggleAiKeyVisibility(){let el=document.querySelector('#ai-key-input');el.type=el.type==='password'?'text':'password'}
function updateAiModelOptions(){let providerId=document.querySelector('#ai-provider-select').value,provider=(window.aiCfg.providers||{})[providerId]||{},models=provider.models||[];document.querySelector('#ai-model-select').innerHTML=models.map(([mid,mlabel])=>`<option value="${esc(mid)}">${esc(mlabel)} (${esc(mid)})</option>`).join('');let badge=document.querySelector('#ai-provider-badge');if(badge){badge.textContent=provider.pricing||'';badge.dataset.pricing=provider.pricing||''}}
function aiKeyHelp(){let providerId=document.querySelector('#ai-provider-select').value,p=(window.aiCfg.providers||{})[providerId];if(!p)return;let n=document.querySelector('#notice');if(!n){n=document.createElement('div');n.id='notice';document.body.appendChild(n)}n.className='notice';n.innerHTML=`<div><b>${L('Obtenir une clé API','Get an API key')} ${esc(p.label)}</b><p>${L('1. Ouvrez la page officielle du fournisseur.\n2. Connectez-vous ou créez votre compte.\n3. Créez une clé API.\n4. Copiez-la.\n5. Revenez ici et collez-la dans le champ Clé API.','1. Open the provider’s official page.\n2. Sign in or create your account.\n3. Create an API key.\n4. Copy it.\n5. Come back here and paste it into the API key field.').replace(/\n/g,'<br>')}</p><div class="row" style="margin-top:.6rem;flex-wrap:wrap"><a href="${esc(p.keyUrl)}" target="_blank" rel="noopener"><button type="button" class="secondary">${L('Ouvrir la page officielle de création de clé','Open the official key creation page')}</button></a><button onclick="this.closest('.notice').remove()">${L('Fermer','Close')}</button></div></div>`}

// ==================================================
// Assistant IA — suggestions (facultatif, jamais de validation automatique)
// ==================================================
function aiConfirmConfidentiality(sid){
  if(localStorage.getItem('epc_ai_confirmed_'+sid))return Promise.resolve(true);
  return new Promise(resolve=>{
    let n=document.querySelector('#notice');if(!n){n=document.createElement('div');n.id='notice';document.body.appendChild(n)}
    n.className='notice';
    n.innerHTML=`<div><b>${L('Confidentialité','Confidentiality')}</b><p>${L('L’utilisation de l’assistant IA transmet au fournisseur sélectionné les données nécessaires à l’analyse. Les réponses individuelles nominatives ne doivent pas être transmises.','Using the AI assistant sends the selected provider the data needed for the analysis. Named individual responses must not be sent.')}</p><div class="row" style="margin-top:.6rem;flex-wrap:wrap"><button class="secondary" id="ai-confirm-cancel">${L('Annuler','Cancel')}</button><button id="ai-confirm-ok">${L('J’ai compris — utiliser l’assistant IA','I understand — use the AI assistant')}</button></div></div>`;
    document.querySelector('#ai-confirm-cancel').onclick=()=>{n.remove();resolve(false)};
    document.querySelector('#ai-confirm-ok').onclick=()=>{localStorage.setItem('epc_ai_confirmed_'+sid,'1');n.remove();resolve(true)};
  });
}
async function aiRun(sid,endpoint,body,onResult,btn){
  let ok=await aiConfirmConfidentiality(sid); if(!ok)return;
  let orig=btn?btn.textContent:null; if(btn){btn.disabled=true;btn.textContent=L('Génération en cours…','Generating…')}
  try{ onResult(await api(endpoint,{method:'POST',body:JSON.stringify(body||{})})) }
  catch(e){ notice(L('Assistant IA momentanément indisponible. Vous pouvez poursuivre l’atelier normalement.','AI assistant temporarily unavailable. You can continue the workshop normally.')+'\n\n('+e.message+')') }
  finally{ if(btn){btn.disabled=false;btn.textContent=orig} }
}
function aiButtonHtml(label,onclick,extraId){return `<button class="secondary ai-btn" ${extraId?`id="${extraId}"`:''} onclick="${onclick}">✦ ${esc(label)}</button>`}
function aiInfoCardHtml(boxId,text,regenFn){return `<div class="card ai-suggestion"><div class="section-header"><h3>✦ ${L('Lecture assistée par IA','AI-assisted reading')}</h3></div><div style="white-space:pre-line">${esc(text)}</div><p class="text-meta" style="margin-top:.6rem">${L('Analyse proposée par l’IA à partir des résultats EPC. Elle ne constitue pas une conclusion validée par le groupe.','Analysis suggested by AI based on EPC results. It is not a conclusion validated by the group.')}</p><div class="row" style="margin-top:.6rem;flex-wrap:wrap"><button class="secondary" onclick="${regenFn}">${L('Régénérer','Regenerate')}</button><button class="ghost" onclick="document.querySelector('#${boxId}').innerHTML=''">${L('Fermer','Close')}</button></div></div>`}
function aiTextRetainCardHtml(boxId,text,retainFn,regenFn){return `<div class="card ai-suggestion"><div class="section-header"><h3>✦ ${L('Suggestion IA','AI suggestion')}</h3></div><textarea class="ai-edit-area" id="${boxId}-text" style="min-height:120px;width:100%">${esc(text)}</textarea><p class="text-meta">${L('Vous pouvez modifier ce texte avant de le retenir.','You can edit this text before keeping it.')}</p><div class="row" style="margin-top:.6rem;flex-wrap:wrap"><button onclick="${retainFn}">${L('Retenir','Keep')}</button><button class="secondary" onclick="${regenFn}">${L('Régénérer','Regenerate')}</button><button class="ghost" onclick="document.querySelector('#${boxId}').innerHTML=''">${L('Ignorer','Ignore')}</button></div></div>`}
function aiListCardHtml(boxId,items,kindLabel,retainItemFn,regenFn){return `<div class="card ai-suggestion"><div class="section-header"><h3>✦ ${L('Hypothèses IA','AI hypotheses')} — ${esc(kindLabel)}</h3></div>${items.map((t,i)=>`<div class="ai-item"><textarea class="ai-edit-area" id="${boxId}-item-${i}" style="width:100%">${esc(t)}</textarea><div class="row" style="margin-top:.3rem"><button class="secondary" onclick="${retainItemFn}(${i},this)">${L('Retenir cette hypothèse','Keep this hypothesis')}</button></div></div>`).join('')}<p class="text-meta" style="margin-top:.4rem">${L('Hypothèses à discuter — aucune n’est présentée comme établie.','Hypotheses to discuss — none is presented as established.')}</p><div class="row" style="margin-top:.6rem;flex-wrap:wrap"><button class="secondary" onclick="${regenFn}">${L('Régénérer','Regenerate')}</button><button class="ghost" onclick="document.querySelector('#${boxId}').innerHTML=''">${L('Ignorer tout','Ignore all')}</button></div></div>`}
async function saveConfigInfo(e,id){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));let cur=(await api('/api/sessions')).find(x=>x.id===id);if(f.name!==cur.name&&window.configHasData){if(!confirm(L(`Attention : cet atelier contient déjà des réponses de participants.\n\nRenommer « ${cur.name} » en « ${f.name} » ne crée PAS un nouvel atelier : cela renomme celui-ci, avec toutes ses données existantes (participants, réponses, résultats).\n\nPour démarrer un atelier réellement vierge, utilisez plutôt « Nouveau diagnostic » depuis l’accueil.\n\nContinuer et renommer quand même ?`,`Warning: this workshop already has participant responses.\n\nRenaming "${cur.name}" to "${f.name}" does NOT create a new workshop: it renames this one, with all its existing data (participants, responses, results).\n\nTo start a truly blank workshop, use "New diagnostic" from the home screen instead.\n\nContinue and rename anyway?`)))return}await api('/api/sessions/'+id,{method:'PUT',body:JSON.stringify({...f,expectedParticipants:cur.expected_participants})});notice(L('Informations enregistrées.','Information saved.'));configuration(id)}
async function saveExpectedParticipants(id){let raw=document.querySelector('#participants-number').value;if(raw===''||raw==null)return notice(L('Veuillez indiquer un nombre de participants prévus avant d’enregistrer.','Please enter an expected number of participants before saving.'));let v=+raw;if(!(v>0))return notice(L('Le nombre de participants prévus doit être supérieur à 0.','The expected number of participants must be greater than 0.'));let cur=(await api('/api/sessions')).find(x=>x.id===id);await api('/api/sessions/'+id,{method:'PUT',body:JSON.stringify({name:cur.name,organization:cur.organization,location:cur.location,date:cur.date,description:cur.description,expectedParticipants:v})});notice(L('Nombre de participants prévus enregistré.','Expected number of participants saved.'));configuration(id)}
