  if(!ready){notice(L('Impossible d’ouvrir la collecte\n\nLe questionnaire ne contient aucun indicateur.\n\n→ Modifiez le questionnaire avant de continuer.','Cannot open collection\n\nThe questionnaire contains no indicators.\n\n→ Edit the questionnaire before continuing.'));return}
