  app.innerHTML=`<article class="report"><div class="report-actions"><button class="secondary" onclick="participantDoneScreen('${sid}','${pid}')">← ${L('Retour','Back')}</button><button class="secondary" onclick="downloadMyResponses('${sid}','${pid}')">${L('Télécharger (fichier)','Download (file)')}</button><button onclick="window.print()">${L('Imprimer / Enregistrer en PDF','Print / Save as PDF')}</button></div>${participantReportBody(d)}</article>`
