  let html=`<!doctype html><html lang="${getLang()}"><head><meta charset="utf-8"><title>${L('Mes réponses','My answers')} — ${esc(d.session.name)}</title><style>body{font-family:sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;color:#111}h1{font-size:1.4rem}h2{font-size:1.1rem;margin-top:1.6rem}p{margin:.3rem 0}</style></head><body>${participantReportBody(d)}</body></html>`;
