const diagnosticBase=diagnostic;diagnostic=async id=>{await diagnosticBase(id);let a=await api('/api/sessions/'+id+'/analysis');app.querySelector('.grid')?.insertAdjacentHTML('afterend',visual(a.domains))};
const domainDiagnosticBase=domainDiagnostic;domainDiagnostic=async(sid,did)=>{await domainDiagnosticBase(sid,did);let a=await api('/api/sessions/'+sid+'/analysis'),d=a.domains.find(x=>x.id===did);app.querySelector('table')?.insertAdjacentHTML('beforebegin',`<h3>${L('Graphique des indicateurs','Indicator chart')}</h3>${bars(d.indicators,'standard',false,'indicator')}`)};
