function renderIndicatorHistogram(did){let d=(window.__histogramDomains||[]).find(x=>x.id===did),body=document.querySelector('#indicator-histogram-body');if(!body||!d)return;body.innerHTML=`<p class="text-meta">${L('Domaine sélectionné','Selected domain')} : <b>${esc(d.label)}</b></p><h4>${L('Standardisé','Standardized')}</h4>${bars(d.indicators,'standard',false,'indicator')}<h4>${L('Gradué','Graded')}</h4>${bars(d.indicators,'graded',false,'indicator')}`}
function domainsTableRows(domains){return `<table><tr><th>${L('Domaine','Domain')}</th><th>${L('Capacité','Capacity')}</th><th>${L('Consensus','Consensus')}</th><th>${L('Graduées','Graded')}</th><th>${L('Niveau','Level')}</th><th>${L('Réponses','Responses')}</th></tr>${domains.map(d=>`<tr><td>${esc(d.label)}</td><td>${fmt(d.capacity)}</td><td>${fmtConsensus(d)}</td><td>${d.gradedCapacity??'—'} / ${d.gradedConsensus??'—'}</td><td>${level(d.capacity)}</td><td>${d.responses}</td></tr>`).join('')}</table>`}
