const filterDiagnosticBase=diagnostic;diagnostic=async id=>{await filterDiagnosticBase(id);app.querySelector('.card')?.insertAdjacentHTML('beforeend',`<details class="card"><summary><h3 style="display:inline">${L('Filtrer / désagréger une sous-population','Filter / break down a subpopulation')}</h3></summary><div class="row row-fields" style="margin-top:.8rem">${PARTICIPANT_PROFILE_FIELDS().map(f=>`<label>${esc(f.label)}<select id="filter-${f.key}"><option value="">${L('Tous','All')}</option>${f.options.map(o=>`<option value="${esc(o)}">${esc(o)}</option>`).join('')}</select></label>`).join('')}</div><button class="secondary" style="margin-top:.6rem" onclick="applyResultFilter('${id}')">${L('Appliquer les filtres','Apply filters')}</button><div id="filter-result" style="margin-top:1rem"></div></details>`)};
